lemma ReflexiveTransitiveAntiSymmetricFiniteFrameClass.is_defined_by_Grz : ReflexiveTransitiveAntiSymmetricFiniteFrameClass.DefinedBy ������ := by
  intro F;
  constructor;
  . rintro ⟨hRefl, hTrans, hAntisymm⟩;
    apply Grz_of_WCWF;
    refine ⟨hRefl, hTrans, ?_⟩;
    apply WCWF_of_finite_trans_antisymm;
    . exact F.world_finite;
    . assumption;
    . assumption;
  . rintro h;
    refine ⟨refl_of_Grz h, trans_of_Grz h, antisymm_of_WCWF $ WCWF_of_Grz h⟩;

instance Grz.consistent : System.Consistent (Hilbert.Grz ℕ) := Kripke.instConsistent_of_nonempty_finiteFrameclass (FC := ReflexiveTransitiveAntiSymmetricFiniteFrameClass) $ by
  use reflexivePointFrame;
  simp [Transitive, Reflexive, AntiSymmetric];

lemma iff_valid_on_canonicalModel_deducible : (canonicalModel H) ⊧ φ ↔ H ⊢! φ := by
  constructor;
  . contrapose;
    intro h;
    have : Theory.Consistent H ({∼φ}) := by
      apply Theory.def_consistent.mpr;
      intro Γ hΓ;
      by_contra hC;
      have : H ⊢! φ := dne'! $ neg_equiv'!.mpr $ replace_imply_left_conj! hΓ hC;
      contradiction;
    obtain ⟨Ω, hΩ⟩ := lindenbaum this;
    simp [Kripke.ValidOnModel];
    use Ω;
    exact truthlemma.not.mpr $ iff_mem_neg.mp (show ∼φ ∈ Ω.theory by simp_all);
  . intro h Ω;
    suffices φ ∈ Ω.theory by exact truthlemma.mpr this;
    by_contra hC;
    obtain ⟨Γ, hΓ₁, hΓ₂⟩ := Theory.iff_insert_inconsistent.mp $ (MaximalConsistentTheory.maximal' hC);
    have : Γ ⊢[H]! ⊥ := FiniteContext.provable_iff.mpr $ and_imply_iff_imply_imply'!.mp hΓ₂ ⨀ h;
    have : Γ ⊬[H] ⊥ := Theory.def_consistent.mp Ω.consistent _ hΓ₁;
    contradiction;

lemma valid_on_frame_T_of_Grz (h : F ⊧* ������) : F ⊧* �� := by
  have := valid_on_frame_T_and_Four_of_Grz h;
  simp_all [ValidOnFrame, ValidOnModel, Axioms.T, Axioms.Grz];
  intro φ V x hx;
  exact Satisfies.and_def.mp (this φ V x hx) |>.1

lemma ReflexiveTransitiveWeaklyConverseWellFoundedFrameClass.is_defined_by_Grz : ReflexiveTransitiveWeaklyConverseWellFoundedFrameClass.DefinedBy ������ := by
  intro F;
  constructor;
  . rintro ⟨hRefl, hTrans, hWCWF⟩;
    apply Grz_of_WCWF;
    exact ⟨hRefl, hTrans, hWCWF⟩;
  . rintro h;
    refine ⟨refl_of_Grz h, trans_of_Grz h, WCWF_of_Grz h⟩;

lemma refl_of_Grz (h : F ⊧* ������) : Reflexive F := by
  apply ReflexiveFrameClass.isDefinedBy F |>.mpr;
  apply valid_on_frame_T_of_Grz h;

