abbrev miniCanonicalFrame (φ : Formula ℕ) : Kripke.FiniteFrame where
  World := CCF (Hilbert.Grz ℕ) (φ.subformulaeGrz)
  Rel X Y :=
    (∀ ψ ∈ □''⁻¹(φ.subformulaeGrz), □ψ ∈ X.formulae → □ψ ∈ Y.formulae) ∧
    ((∀ ψ ∈ □''⁻¹(φ.subformulaeGrz), □ψ ∈ Y.formulae → □ψ ∈ X.formulae) → X = Y)

